from pathlib import Path

from yamalemma.adjudicate import adjudicate
from yamalemma.domain import fingerprint, make_claim, make_probe, save_json
from yamalemma.harness import check_probe
from yamalemma.ingest import ingest_source
from yamalemma.report import write_report
from yamalemma.storage import ArtifactStore
from yamalemma.templates import proposition as template_proposition


CASES = [
    ('S03', 'E6.a5_excluded', 'extra_hyp', 'instance', 'confirm',
     'The cyclic group of order three is generated by one element, so the extra non-generation hypothesis excludes it.',
     'Check the finite-group, generation, odd-order, and informal admissibility conditions together; this certificate checks only the closure equality.'),
    ('S06', 'E4.docstring_2021_b4_false', 'docstring_mismatch', 'translated', 'confirm',
     'The formalized docstring claim fails at the displayed Fibonacci-product example.',
     'Compare the transcribed bound with the official problem and answer to establish which text requires correction.'),
    ('S08', 'E4.B82_parse', 'precedence', 'parse', 'confirm',
     'The abstracted conclusion parses as an implication rather than a required convergence assertion followed by continuity.',
     'Connect the parsed conclusion to the original recurrence and domain. B82_weaker does not satisfy those original assumptions.'),
    ('S09', 'E4.A6_trivial', 'vacuous', 'intrinsic', 'confirm',
     'The statement with the recorded positive-natural answer substitution has a proof exploiting the strategy condition.',
     'Validate the answer substitution and intended strategy rules. Length-one games are handled separately; this is not a claim that all games are invalid.'),
    ('S11', 'E4.scope_2004_a4', 'scope', 'schema', 'confirm',
     'The generalized pointwise and uniform logical forms can differ.',
     'Explain the omitted uniformity requirement for the actual product. The schema counterexample does not show a truth-value difference for that product.'),
    ('S10', 'E5c.general_index_uses_nat', 'coercion_junk', 'parse', 'refute',
     'Some matrix index disagrees with its explicitly expanded natural-number expression.',
     'The refutation concerns only this arithmetic interpretation, not every aspect of the benchmark.'),
    ('S12', 'E5c.index_uses_nat', 'coercion_junk', 'parse', 'refute',
     'Some index disagrees with its explicitly expanded natural-number expression.',
     'The refutation concerns only the index expression. The n=0 determinant example is not a witness for all original hypotheses.'),
]


def run_demo(worker, root, output):
    root, output = Path(root), Path(output)
    paths = [root / 'lean/fixtures/E5_audit.lean', root / 'lean/fixtures/E6_audit.lean', root / 'fixtures/prior/E4.lean']
    items = {item['id']: item for path in paths for item in ingest_source(worker, path)}
    store = ArtifactStore(output / 'artifacts')
    summary = []
    for case_id, theorem, kind, bridge, polarity, prediction, obligation in CASES:
        item = items[theorem]
        item['development_case'] = case_id
        item['benchmark_reference'] = 'historical blind-audit snapshot (not distributed)'
        item['benchmark_reference_sha256'] = 'de723602caa8129d60a6ab8c6077efb43886c75f45020a47421166ecf9ce5a26'
        adaptations = {
            'S08': 'abstract the conclusion; omit the original recurrence and domain hypotheses',
            'S09': 'substitute the recorded answer {n : Nat | 0 < n} for the benchmark answer placeholder',
            'S11': 'replace the concrete product with an arbitrary function and use the absolute-value schema instance',
            'S06': 'formalize the informal docstring as the displayed Fibonacci-product proposition',
        }
        if case_id in adaptations:
            item['transformations'].append(adaptations[case_id])
        item['fingerprint'] = fingerprint({key: value for key, value in item.items() if key != 'fingerprint'})
        proposition = template_proposition('proposition', statement=item['expected_type'])
        proof = item['proof']
        if polarity == 'refute':
            proposition = f'Not ({proposition})'
            proof = f'fun h => h ({proof})'
        scope = 'selected expression' if polarity == 'refute' else ('generalized schema' if bridge == 'schema' else 'recorded certificate proposition')
        claim = make_claim(item, case_id, proposition, prediction, kind, scope, bridge, obligation)
        probe = make_probe(claim, polarity, proof)
        evidence = [check_probe(worker, item, claim, probe, store)]
        verdict = adjudicate(claim, evidence)
        write_report(output / case_id, item, claim, evidence, verdict)
        save_json(output / case_id / 'item.json', item)
        save_json(output / case_id / 'claim.json', claim)
        save_json(output / case_id / 'probe.json', probe)
        (output / case_id / 'proof.lean').write_text(proof + '\n')
        summary.append({'case': case_id, 'theorem': theorem, 'verdict': verdict['evidence_verdict'],
                        'finding_status': verdict['finding_status'], 'report': str(output / case_id / 'report.md')})
        print(f'{case_id}: {verdict["evidence_verdict"]}', flush=True)
    save_json(output / 'summary.json', summary)
    return summary
